+          type = "app";
+          program = "${pkgs.writeShellScript "fleet-format" ''
+            export PATH="${
+              pkgs.lib.makeBinPath [
+                pkgs.treefmt
+                pkgs.nixfmt
+                pkgs.shfmt
+              ]
+            }:$PATH"
+            exec treefmt --no-cache "$@"
+          ''}";
+        };
+      });
     };
