+    steps:
+      - name: Normalize and validate target
+        id: target
+        env:
+          PLATFORM_INPUT: ${{ inputs.platform }}
+          PLATFORM_EVENT: ${{ github.event.inputs.platform }}
+          RUNNER_INPUT: ${{ inputs.runner }}
+          RUNNER_EVENT: ${{ github.event.inputs.runner }}
+          TIMEOUT_INPUT: ${{ inputs.timeout_minutes }}
+          TIMEOUT_EVENT: ${{ github.event.inputs.timeout_minutes }}
