+        run: |
+          set -euo pipefail
+          platform="${PLATFORM_INPUT:-${PLATFORM_EVENT:-linux}}"
+          runner="${RUNNER_INPUT:-${RUNNER_EVENT:-github}}"
+          timeout="${TIMEOUT_INPUT:-${TIMEOUT_EVENT:-60}}"
+          case "$platform" in
+            linux|macos) ;;
+            *) echo "::error::platform must be linux or macos (got $platform)"; exit 2 ;;
+          esac
+          case "$runner" in
+            github|blacksmith) ;;
+            *) echo "::error::runner must be github or blacksmith (got $runner)"; exit 2 ;;
+          esac
+          if [[ ! "$timeout" =~ ^[0-9]+$ ]] || [ "$timeout" -lt 5 ] || [ "$timeout" -gt 120 ]; then
+            echo "::error::timeout_minutes must be between 5 and 120 (got $timeout)"
+            exit 2
+          fi
+          if [ "$runner" = blacksmith ] && [ "$WORKFLOW_REPO" != developing-today/fleet ]; then
+            echo "::error::Blacksmith is configured only for developing-today/fleet"
+            exit 2
+          fi
+          if [ "$runner" = blacksmith ] && [ "$platform" = macos ]; then
+            echo "::error::Blacksmith is Linux-only; select runner=github for macOS"
+            exit 2
+          fi
+          printf 'platform=%s\nrunner=%s\ntimeout_minutes=%s\n' "$platform" "$runner" "$timeout" >> "$GITHUB_OUTPUT"
+          echo "Selected platform=$platform runner=$runner timeout_minutes=$timeout"
